# C:Users\u000BladeOneDriveDocumentosGitHubStrategicFlow\backendsrcmodulescrmmodels.pyfrom dataclasses import dataclassfrom datetime import datetimefrom typing import Optional, List# ============================================# 🗄️ ENTIDADE: CLIENTE (Company) - TABELA: clients# ============================================# 👉 INSERT: INSERT INTO clients (razao_social, cnpj, ...) VALUES (...)# 👉 UPDATE: UPDATE clients SET razao_social = ?, status = ? WHERE id = ?# 👉 DELETE: DELETE FROM clients WHERE id = ?# 👉 SELECT: SELECT * FROM clients WHERE id = ? OR WHERE tenant_id = ?@dataclassclass Client:    """    Cliente corporativo (Company) - Dados corporativos    - Relacionamento 1:N com Contato, Oportunidade, Interação    """    id: int    razao_social: str              # 👉 INSERT: Razão social da empresa    nome_fantasia: Optional[str]   # 👉 INSERT: Nome fantasia    cnpj: Optional[str]            # 👉 INSERT: CNPJ da empresa    segmento: Optional[str]        # 👉 INSERT: Segmento (Tecnologia, Indústria, etc)    porte_empresa: Optional[str]   # 👉 INSERT: Porte (Pequeno, Médio, Grande)    numero_funcionarios: Optional[int]  # 👉 INSERT: Número de funcionários    email: Optional[str]           # 👉 INSERT: Email corporativo    phone: Optional[str]           # 👉 INSERT: Telefone    site: Optional[str]            # 👉 INSERT: Site da empresa    endereco: Optional[str]        # 👉 INSERT: Endereço completo    cidade: Optional[str]          # 👉 INSERT: Cidade    estado: Optional[str]          # 👉 INSERT: Estado (UF)    cep: Optional[str]             # 👉 INSERT: CEP    status: str = "ativo"          # 👉 UPDATE: Status (ativo, inativo, lead)    nps_score: Optional[int]       # 👉 UPDATE: NPS Score (0-100)    tenant_id: str = "default-tenant"    created_at: datetime = datetime.now()    updated_at: datetime = datetime.now()# ============================================# 🗄️ ENTIDADE: CONTATO (Contact) - TABELA: contacts# ============================================# 👉 INSERT: INSERT INTO contacts (client_id, nome, cargo, email, ...) VALUES (...)# 👉 UPDATE: UPDATE contacts SET nome = ?, cargo = ? WHERE id = ?# 👉 DELETE: DELETE FROM contacts WHERE id = ? OR WHERE client_id = ? (quando deletar cliente)# 👉 SELECT: SELECT * FROM contacts WHERE client_id = ?@dataclassclass Contact:    """    Contato pessoa física ligada ao cliente    - Relacionamento N:1 com Cliente (1 Cliente tem N Contatos)    """    id: int    client_id: int                 # 👉 INSERT: FK - Cliente vinculado    nome: str                      # 👉 INSERT: Nome do contato    cargo: Optional[str]           # 👉 INSERT: Cargo/Função    email: Optional[str]           # 👉 INSERT: Email do contato    phone: Optional[str]           # 👉 INSERT: Telefone do contato    whatsapp: Optional[str]        # 👉 INSERT: WhatsApp    data_nascimento: Optional[datetime]    is_principal: bool = False     # 👉 INSERT: Contato principal (booleano)    tenant_id: str = "default-tenant"    created_at: datetime = datetime.now()# ============================================# 🗄️ ENTIDADE: OPORTUNIDADE (Deal/Funil) - TABELA: opportunities# ============================================# 👉 INSERT: INSERT INTO opportunities (client_id, title, stage, value_expected, ...) VALUES (...)# 👉 UPDATE: UPDATE opportunities SET stage = ?, value_closed = ? WHERE id = ?# 👉 DELETE: DELETE FROM opportunities WHERE id = ? OR WHERE client_id = ?# 👉 SELECT: SELECT * FROM opportunities WHERE client_id = ? OR WHERE stage = ?@dataclassclass Opportunity:    """    Oportunidade (Deal) - Ciclo de vendas da consultoria    - Relacionamento N:1 com Cliente (1 Cliente tem N Oportunidades)    - Estágios: diagnostico, proposta, negociação, fechado_positivo, fechado_negativo    """    id: int    client_id: int                 # 👉 INSERT: FK - Cliente vinculado    title: str                     # 👉 INSERT: Título da oportunidade    description: Optional[str]     # 👉 INSERT: Descrição detalhada    stage: str = "diagnostico"     # 👉 UPDATE: Estágio (funil de vendas)    value_expected: Optional[float] # 👉 INSERT: Valor esperado (R$)    value_closed: Optional[float]   # 👉 UPDATE: Valor fechado (R$)    probability: Optional[float] = 50.0  # 👉 INSERT: Probabilidade de fechamento (%)    expected_close_date: Optional[datetime]  # 👉 INSERT: Data prevista de fechamento    closed_date: Optional[datetime]        # 👉 UPDATE: Data real de fechamento    owner: Optional[str]           # 👉 INSERT: Consultor responsável    tenant_id: str = "default-tenant"    created_at: datetime = datetime.now()    updated_at: datetime = datetime.now()# ============================================# 🗄️ ENTIDADE: INTERAÇÃO (Interaction) - TABELA: interactions# ============================================# 👉 INSERT: INSERT INTO interactions (client_id, opportunity_id, type, title, description, date, ...) VALUES (...)# 👉 UPDATE: UPDATE interactions SET description = ?, next_action = ? WHERE id = ?# 👉 DELETE: DELETE FROM interactions WHERE id = ?# 👉 SELECT: SELECT * FROM interactions WHERE client_id = ? OR WHERE opportunity_id = ?@dataclassclass Interaction:    """    Atendimento/Interação - Registro de discussões    - Relacionamento N:1 com Cliente ou Oportunidade    - Tipos: reuniao, email, telefone, visita, nota    """    id: int    client_id: int                 # 👉 INSERT: FK - Cliente vinculado    opportunity_id: Optional[int] = None  # 👉 INSERT: FK - Oportunidade vinculado (opcional)    type: str = "reuniao"          # 👉 INSERT: Tipo (reuniao, email, telefone, visita, nota)    title: str                     # 👉 INSERT: Título da interação    description: str               # 👉 INSERT: Descrição detalhada (notas)    date: datetime                 # 👉 INSERT: Data/hora da interação    duration_minutes: Optional[int]  # 👉 INSERT: Duration (minutos)    participant_names: Optional[str]   # 👉 INSERT: Participantes (separados por ;)    next_action: Optional[str]     # 👉 UPDATE: Ação futura planejada    next_action_date: Optional[datetime]  # 👉 UPDATE: Data da ação futura    tenant_id: str = "default-tenant"    created_at: datetime = datetime.now()# ============================================# 🗄️ ENTIDADE: PROJETO (Project) - TABELA: projects# ============================================# 👉 INSERT: INSERT INTO projects (client_id, opportunity_id, name, scope, status, hours_contracted, ...) VALUES (...)# 👉 UPDATE: UPDATE projects SET status = ?, hours_used = ?, end_date = ? WHERE id = ?# 👉 DELETE: DELETE FROM projects WHERE id = ?# 👉 SELECT: SELECT * FROM projects WHERE client_id = ? OR WHERE status = 'ativo'@dataclassclass Project:    """    Projeto - Quando venda é fechada, oportunidade converte em projeto    - Relacionamento N:1 com Cliente e Oportunidade    """    id: int    client_id: int                 # 👉 INSERT: FK - Cliente vinculado    opportunity_id: Optional[int] = None  # 👉 INSERT: FK - Oportunidade que gerou projeto    name: str                      # 👉 INSERT: Nome do projeto    description: Optional[str]     # 👉 INSERT: Descrição    scope: Optional[str]           # 👉 INSERT: Escopo do projeto    status: str = "planejamento"   # 👉 UPDATE: Status (planejamento, ativo, paused, concluido, cancelado)    priority: str = "média"        # 👉 INSERT: Prioridade (baixa, média, alta, crítica)    start_date: Optional[datetime]  # 👉 INSERT: Data de início    end_date: Optional[datetime]    # 👉 UPDATE: Data de término    budget: Optional[float]        # 👉 INSERT: Budget (R$)    hours_contracted: Optional[int]  # 👉 INSERT: Horas contratadas    hours_used: Optional[int] = 0    # 👉 UPDATE: Horas utilizadas (progresso)    consultants: Optional[str]     # 👉 INSERT: Consultores alocados (IDs separados por ;)    manager: Optional[str]         # 👉 INSERT: Gerente do projeto    tenant_id: str = "default-tenant"    created_at: datetime = datetime.now()    updated_at: datetime = datetime.now()# ============================================# 🗄️ ENTIDADE: KPI CRM (para dashboard) - TABELA: kpis (ou calcular dinâmico)# ============================================# 👉 INSERT: INSERT INTO kpis (name, value, tenant_id) VALUES ('conversion_rate', 75.5, ...)# 👉 UPDATE: UPDATE kpis SET value = ? WHERE name = 'conversion_rate' AND tenant_id = ?# 👉 SELECT: SELECT * FROM kpis WHERE tenant_id = ?@dataclassclass CrmKpi:    """KPIs do CRM para o dashboard"""    name: str    value: float    unit: str    tenant_id: str = "default-tenant"